Step.SQLStatement:
-- Unique index: scope code unique per client (AD_TokenScope)
        CREATE UNIQUE INDEX IF NOT EXISTS ad_tokenscope_value_uq
        ON ad_tokenscope (ad_client_id, value);

        -- Unique index: profile code unique per client (AD_TokenProfile)
        CREATE UNIQUE INDEX IF NOT EXISTS ad_tokenprofile_value_uq
        ON ad_tokenprofile (ad_client_id, value);

        -- Unique index: one scope per profile (AD_TokenProfileScope)
        CREATE UNIQUE INDEX IF NOT EXISTS ad_tokenprofilescope_uq
        ON ad_tokenprofilescope (ad_tokenprofile_id, ad_tokenscope_id);

Step.RollbackStatement:
DROP INDEX IF EXISTS ad_tokenscope_value_uq;
        DROP INDEX IF EXISTS ad_tokenprofile_value_uq;
        DROP INDEX IF EXISTS ad_tokenprofilescope_uq;
